    /// <summary><c>stream</c>: Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped.</summary>
    /// <remarks>URL names: <c>stream</c>, <c>st</c>; arguments <c>protocol:height…</c>; default none (a file). Milestone M5 (WP-126); scope request.</remarks>
    public sealed record Stream : VideoOption
    {
        /// <summary>Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped.</summary>
        /// <remarks>URL names: <c>stream</c>, <c>st</c>; arguments <c>protocol:height…</c>; default none (a file). Milestone M5 (WP-126); scope request.</remarks>
        /// <param name="protocol">manifest: HLS (m3u8) or DASH (mpd). One of <c>dash</c>, <c>hls</c>.</param>
        /// <param name="heights">Repeated argument: height — a rendition by the short side of its frame. Range ≥ 64, ≤ 4320. Null writes an empty argument.</param>
        public Stream(string protocol, params long[] heights)
            : base("stream", Args0(protocol, heights))
        {
        }

        private static OptionArg[] Args0(string protocol, long[] heights)
        {
            ArgumentNullException.ThrowIfNull(heights);
            var args = new List<OptionArg>(1 + (heights.Length * 1)) { protocol };
            foreach (var e in heights)
            {
                args.Add(e);
            }

            return [.. args];
        }
    }

